var (
	// We need this package because time.Now() is slower, allocates memory,
	// and we don't need a more precise time for the expiry time (and most other operations).
	now uint32

	// startTime is the Unix timestamp (seconds since January 1, 1970 UTC) when the timer was started.
	// It is used to convert the relative time returned by Now() to an absolute time.
	startTime int64

	mutex         sync.Mutex
	countInstance int
	done          chan struct{}
)

func startTimer() {
	done = make(chan struct{})
	atomic.StoreInt64(&startTime, time.Now().Unix())
	atomic.StoreUint32(&now, uint32(0))

	go func() {
		ticker := time.NewTicker(time.Second)
		defer ticker.Stop()
		for {
			select {
			case t := <-ticker.C:
				atomic.StoreUint32(&now, uint32(t.Unix()-atomic.LoadInt64(&startTime)))
			case <-done:
				return
			}
		}
	}()
}

// Start should be called when the cache instance is created to initialize the timer.
func Start() {
	mutex.Lock()
	defer mutex.Unlock()

	if countInstance == 0 {
		startTimer()
	}

	countInstance++
}

// Stop should be called when closing and stopping the cache instance to stop the timer.
func Stop() {
	mutex.Lock()
	defer mutex.Unlock()

	countInstance--
	if countInstance == 0 {
		done <- struct{}{}
		close(done)
	}
}

