func SetNow(t uint32) {
	atomic.StoreUint32(&now, t)
}

// StartTime returns the Unix timestamp (seconds since January 1, 1970 UTC) when the timer was started.
func StartTime() int64 {
	return atomic.LoadInt64(&startTime)
